/**
 * Domain types for the teacher-profiles module.
 *
 * These are hand-written for now. Once `openapi.yaml` exists, the real request/
 * response types will be generated by `openapi-typescript` and these will either
 * be deleted or narrowed to view-models. Keeping the shape close to what the API
 * will return keeps the swap cheap.
 */

/** ISO 4217 currency, amounts always in MINOR units (cents) to avoid float math. */
export interface Money {
  /**
   * Amount in MINOR units. For UZS that's tiyin (1/100 so'm) — never displayed,
   * but kept so the field means the same thing for every currency and matches
   * how Stripe represents amounts.
   */
  amountMinor: number;
  currency: "UZS" | "USD";
}

export type LanguageLevel =
  | "native"
  | "c2"
  | "c1"
  | "b2"
  | "b1"
  | "a2"
  | "a1";

export interface SpokenLanguage {
  /** ISO 639-1, e.g. "es" */
  code: string;
  name: string;
  level: LanguageLevel;
}

/**
 * italki-style distinction:
 * - "professional": certified/qualified teacher, structured lessons
 * - "community": conversation practice, informal tutoring
 */
export type TeacherKind = "professional" | "community";

/** A card-sized view of a teacher, used in search results and listings. */
export interface TeacherSummary {
  id: string;
  /** URL-safe, stable, used in /teachers/[slug] */
  slug: string;
  displayName: string;
  /** one-line hook, shown under the name */
  headline: string;
  avatarUrl: string;
  /** poster frame for the intro video */
  videoThumbnailUrl: string;
  kind: TeacherKind;
  /** ISO 3166-1 alpha-2 */
  countryCode: string;
  countryName: string;
  /** where the teacher is based, shown with the country */
  city: string;
  /** IANA tz, e.g. "America/Bogota" — the source of truth for slot conversion */
  timezone: string;
  teaches: SpokenLanguage[];
  alsoSpeaks: SpokenLanguage[];
  pricePerHour: Money;
  /** 0–5, one decimal */
  rating: number;
  reviewCount: number;
  lessonsCompleted: number;
  studentCount: number;
  /** free-text focus tags: "Conversational", "Business", "Exam prep", "Kids" */
  focus: string[];
  /** median hours to reply to a booking request */
  responseTimeHours: number;
  /** teacher currently accepting new students */
  acceptingStudents: boolean;
}

/** Everything on a full profile page. Extends the summary with long-form content. */
export interface TeacherProfile extends TeacherSummary {
  introVideoUrl: string;
  /** long-form, plain text with paragraph breaks on \n\n */
  about: string;
  /** how the teacher runs a lesson */
  teachingStyle: string;
  /** credentials / relevant history, newest first */
  experience: ExperienceItem[];
  /** trial lesson price, if offered */
  trialPrice?: Money;
}

export interface ExperienceItem {
  title: string;
  org: string;
  /** e.g. "2019 – present" */
  period: string;
}
